import fs from "fs";
import path from "path";
import crypto from "crypto";

const DB_PATH = path.join(process.cwd(), 'local-db.json');

// Helper to read and write database
function readDb(): Record<string, any[]> {
  try {
    if (fs.existsSync(DB_PATH)) {
      const content = fs.readFileSync(DB_PATH, 'utf8');
      return JSON.parse(content);
    }
  } catch (e) {
    console.error("Error reading local db file", e);
  }
  return {};
}

function writeDb(data: Record<string, any[]>) {
  try {
    fs.writeFileSync(DB_PATH, JSON.stringify(data, null, 2), 'utf8');
  } catch (e) {
    console.error("Error writing to local db file", e);
  }
}

function resolveValue(existingVal: any, newVal: any) {
  if (newVal && typeof newVal === 'object' && newVal.__arrayUnion) {
    const existingArray = Array.isArray(existingVal) ? existingVal : [];
    const unionVals = newVal.__arrayUnion;
    const resolved = [...existingArray];
    for (const val of unionVals) {
      if (!resolved.some(x => JSON.stringify(x) === JSON.stringify(val))) {
        resolved.push(val);
      }
    }
    return resolved;
  }
  return newVal;
}

export const AdminFieldValue = {
  serverTimestamp: () => new Date().toISOString(),
  arrayUnion: (...vals: any[]) => ({ __arrayUnion: vals })
};

class LocalQuery {
  private collectionName: string;
  private filters: Array<{ field: string, op: string, value: any }> = [];
  private orderField: string | null = null;
  private orderDir: 'asc' | 'desc' = 'asc';
  private limitCount: number | null = null;

  constructor(collectionName: string) {
    this.collectionName = collectionName;
  }

  where(field: string, op: string, value: any): LocalQuery {
    this.filters.push({ field, op, value });
    return this;
  }

  orderBy(field: string, dir: 'asc' | 'desc' = 'asc'): LocalQuery {
    this.orderField = field;
    this.orderDir = dir;
    return this;
  }

  limit(count: number): LocalQuery {
    this.limitCount = count;
    return this;
  }

  async get() {
    const dbData = readDb();
    let records = dbData[this.collectionName] || [];

    // Apply filters
    for (const filter of this.filters) {
      records = records.filter(item => {
        let itemVal = item[filter.field];
        let filterVal = filter.value;

        // Normalize timestamp objects
        if (itemVal && typeof itemVal === 'object' && itemVal.toDate) {
          itemVal = itemVal.toDate().toISOString();
        }
        if (filterVal && typeof filterVal === 'object' && filterVal.toDate) {
          filterVal = filterVal.toDate().toISOString();
        }

        switch (filter.op) {
          case '==':
            return itemVal === filterVal;
          case '!=':
            return itemVal !== filterVal;
          case '>':
            return itemVal > filterVal;
          case '>=':
            return itemVal >= filterVal;
          case '<':
            return itemVal < filterVal;
          case '<=':
            return itemVal <= filterVal;
          case 'in':
            return Array.isArray(filterVal) && filterVal.includes(itemVal);
          case 'array-contains':
            return Array.isArray(itemVal) && itemVal.includes(filterVal);
          default:
            return false;
        }
      });
    }

    // Apply sorting
    if (this.orderField) {
      const field = this.orderField;
      const dir = this.orderDir === 'desc' ? -1 : 1;
      records.sort((a, b) => {
        const valA = a[field];
        const valB = b[field];
        if (valA < valB) return -1 * dir;
        if (valA > valB) return 1 * dir;
        return 0;
      });
    }

    // Apply limit
    if (this.limitCount !== null) {
      records = records.slice(0, this.limitCount);
    }

    const docs = records.map(record => ({
      id: record.id,
      exists: true,
      ref: { id: record.id },
      data: () => record
    }));

    return {
      size: docs.length,
      empty: docs.length === 0,
      docs,
      forEach: (cb: any) => docs.forEach(cb)
    };
  }
}

export class LocalDocRef {
  private collectionName: string;
  public id: string;

  constructor(collectionName: string, id: string) {
    this.collectionName = collectionName;
    this.id = id;
  }

  async get() {
    const dbData = readDb();
    const records = dbData[this.collectionName] || [];
    const found = records.find(r => r.id === this.id);
    return {
      exists: !!found,
      id: this.id,
      data: () => found ? found : undefined
    };
  }

  async set(data: any, options?: { merge?: boolean }) {
    const dbData = readDb();
    if (!dbData[this.collectionName]) {
      dbData[this.collectionName] = [];
    }

    const records = dbData[this.collectionName];
    const index = records.findIndex(r => r.id === this.id);

    const cleanData: any = { ...data };
    for (const [k, v] of Object.entries(cleanData)) {
      if (typeof v === 'function' || (v && typeof v === 'object' && v.constructor?.name === 'FieldValue')) {
        cleanData[k] = new Date().toISOString();
      }
    }

    const payload = { id: this.id, ...cleanData };

    if (index >= 0) {
      if (options?.merge) {
        records[index] = { ...records[index], ...payload };
      } else {
        records[index] = payload;
      }
    } else {
      records.push(payload);
    }

    writeDb(dbData);
  }

  async update(data: any) {
    const dbData = readDb();
    const records = dbData[this.collectionName] || [];
    const index = records.findIndex(r => r.id === this.id);

    if (index >= 0) {
      const existing = records[index];
      const updated = { ...existing };
      for (const [k, v] of Object.entries(data)) {
        if (typeof v === 'function' || (v && typeof v === 'object' && v.constructor?.name === 'FieldValue')) {
          updated[k] = new Date().toISOString();
        } else {
          updated[k] = resolveValue(existing[k], v);
        }
      }
      records[index] = updated;
      writeDb(dbData);
    }
  }

  async delete() {
    const dbData = readDb();
    const records = dbData[this.collectionName] || [];
    const filtered = records.filter(r => r.id !== this.id);
    dbData[this.collectionName] = filtered;
    writeDb(dbData);
  }
}

class LocalCollection {
  private collectionName: string;

  constructor(collectionName: string) {
    this.collectionName = collectionName;
  }

  doc(id?: string): LocalDocRef {
    const docId = id || crypto.randomUUID();
    return new LocalDocRef(this.collectionName, docId);
  }

  where(field: string, op: string, value: any): LocalQuery {
    const q = new LocalQuery(this.collectionName);
    return q.where(field, op, value);
  }

  orderBy(field: string, dir: 'asc' | 'desc' = 'asc'): LocalQuery {
    const q = new LocalQuery(this.collectionName);
    return q.orderBy(field, dir);
  }

  limit(count: number): LocalQuery {
    const q = new LocalQuery(this.collectionName);
    return q.limit(count);
  }

  async add(data: any): Promise<LocalDocRef> {
    const id = crypto.randomUUID();
    const docRef = new LocalDocRef(this.collectionName, id);
    await docRef.set(data);
    return docRef;
  }

  async get() {
    const q = new LocalQuery(this.collectionName);
    return q.get();
  }
}

class LocalBatch {
  private operations: Array<() => Promise<void>> = [];

  delete(ref: any) {
    this.operations.push(async () => {
      await ref.delete();
    });
    return this;
  }

  set(ref: any, data: any, options?: any) {
    this.operations.push(async () => {
      await ref.set(data, options);
    });
    return this;
  }

  update(ref: any, data: any) {
    this.operations.push(async () => {
      await ref.update(data);
    });
    return this;
  }

  async commit() {
    for (const op of this.operations) {
      await op();
    }
  }
}

export class LocalBackendDB {
  collection(name: string): LocalCollection {
    return new LocalCollection(name);
  }

  batch(): LocalBatch {
    return new LocalBatch();
  }
}
