async function generateContentWithRetry(ai: any, params: any, maxRetries = 3) {
  let attempt = 0;
  while (true) {
    try {
      return await ai.models.generateContent(params);
    } catch (error: any) {
      attempt++;
      const errorMessage = error.message || "";
      const errorStatus = error.status || error.code || "";
      
      const isUnavailable = 
        errorStatus === 503 || 
        errorStatus === "UNAVAILABLE" || 
        String(errorStatus).includes("503") || 
        errorMessage.includes("503") || 
        errorMessage.toUpperCase().includes("UNAVAILABLE") ||
        errorMessage.toUpperCase().includes("HIGH DEMAND") ||
        errorMessage.toUpperCase().includes("BUSY") ||
        errorMessage.toUpperCase().includes("RESOURCE_EXHAUSTED");

      if (isUnavailable && attempt < maxRetries) {
        const backoffDelay = Math.pow(2, attempt) * 1000;
        console.warn(`[Feen Engine Server Retry] Gemini 503 high demand detected. Retrying in ${backoffDelay}ms... (Attempt ${attempt}/${maxRetries})`);
        await new Promise((resolve) => setTimeout(resolve, backoffDelay));
        continue;
      }
      throw error;
    }
  }
}

function handleGeminiError(error: any, res: any, contextMessage: string) {
  const errorMessage = error.message || "";
  const errorStatus = error.status || error.code || "";
  
  const isUnavailable = 
    errorStatus === 503 || 
    errorStatus === "UNAVAILABLE" || 
    String(errorStatus).includes("503") || 
    errorMessage.includes("503") || 
    errorMessage.toUpperCase().includes("UNAVAILABLE") ||
    errorMessage.toUpperCase().includes("HIGH DEMAND") ||
    errorMessage.toUpperCase().includes("BUSY") ||
    errorMessage.toUpperCase().includes("RESOURCE_EXHAUSTED");

  if (isUnavailable) {
    return res.status(200).json({
      success: false,
      code: 503,
      status: "UNAVAILABLE",
      error: "The AI Tutor is currently busy handling other students. Please wait a moment and try again!",
      message: "The AI Tutor is currently busy handling other students. Please wait a moment and try again!"
    });
  }

  return res.status(500).json({
    success: false,
    error: errorMessage || contextMessage,
    message: errorMessage || contextMessage
  });
}


