  // Helper function to detect and prevent unauthorized Student access to Home Tuition modules
  async function isStudentRequest(req: any): Promise<boolean> {
    try {
      // 1. Check explicit role headers
      const roleHeaders = [
        req.headers['x-user-role'],
        req.headers['x-current-view-role'],
        req.headers['x-simulation-role'],
        req.headers['role'],
        req.headers['user-role']
      ];
      for (const h of roleHeaders) {
        if (h && String(h).toLowerCase() === 'student') {
          return true;
        }
      }

      // 2. Extract and check token
      const authHeader = req.headers['authorization'];
      let token = req.cookies?.feen_admin_token || req.cookies?.auth_token || req.cookies?.token;
      if (!token && authHeader && authHeader.startsWith('Bearer ')) {
        token = authHeader.split(' ')[1];
      }

      if (token) {
        // Try verifying custom JWT admin token first
        try {
          const decoded = jwt.verify(token, JWT_SECRET) as any;
          if (decoded && decoded.role === 'student') {
            return true;
          }
        } catch (jwtErr) {
          // Token is not a custom admin token, could be Firebase ID Token
        }

        // Decode Firebase JWT token directly to locate user UID in 'sub' claim
        const decodedFirebase: any = jwt.decode(token);
        if (decodedFirebase && decodedFirebase.sub) {
          const uid = decodedFirebase.sub;
          const userDoc = await adminDb.collection('users').doc(uid).get();
          if (userDoc.exists) {
            const uData = userDoc.data();
            if (uData && uData.role === 'student') {
              return true;
            }
          }
        }
      }

      // 3. Check query parameters or body for direct uid reference
      const uid = req.query?.uid || req.body?.uid || req.headers['uid'] || req.headers['user-id'];
      if (uid) {
        const userDoc = await adminDb.collection('users').doc(String(uid)).get();
        if (userDoc.exists) {
          const uData = userDoc.data();
          if (uData && uData.role === 'student') {
            return true;
          }
        }
      }
    } catch (err) {
      console.error("isStudentRequest verification error:", err);
    }
    return false;
  }

